@app.middleware("http")
async def require_token_for_writes(request: Request, call_next):
    if request.method in ("POST", "PUT", "PATCH", "DELETE"):
        required = os.environ.get("TUBESCOUT_PAGE_TOKEN", "").strip()
        if required:
            supplied = (request.query_params.get("token")
                        or request.headers.get("X-TubeScout-Token", ""))
            if supplied != required:
                return JSONResponse(
                    {"status": "error", "error": "write access requires token"},
                    status_code=401)
    return await call_next(request)

